// contactLabel renders a draft's contact with the CRM name when known.
func contactLabel(contacts CRMContacts, contact string) string {
	if known, ok := contacts[contact]; ok && known.Name != "" {
		return known.Name + " · +" + contact
	}
	return "+" + contact
}

